insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8ae8c1d6-4a69-4a78-8255-8f7a954e4608', 'es', 'Cafetería. Comentas lo larga que está la fila. Ella sonríe, responde con una broma y se gira hacia ti.', '["Está siendo cortés porque hablaste primero", "Está abierta y dispuesta a seguir", "Está matando el tiempo mientras espera"]'::jsonb, 'El humor y girarse hacia ti muestran interés. Está participando, no solo respondiendo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8ce90839-46ac-4c09-88d3-7e5231bbade8', 'es', 'Ves en su brazo un tatuaje con un diseño muy bueno. ¿Qué apertura muestra curiosidad?', '["“¿Qué historia hay detrás de ese tatuaje? Me encanta.”", "“Ese tatuaje se te ve muy sexy.”", "“Tienes un estilo muy bueno.”", "“¿Tienes más tatuajes?”"]'::jsonb, 'La curiosidad por sus experiencias invita a una conexión real, sin intenciones ocultas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90a2ae5f-3f19-4289-983b-90a3660b1de9', 'es', '¿Qué pasa cuando alguien ignora las señales corteses o frías?', '["La atracción crece poco a poco", "La comodidad disminuye", "La interacción se hace más profunda", "El interés se aclara"]'::jsonb, 'Ignorar las señales aumenta la tensión y la incomodidad; despídete en cuanto las notes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('92fc8147-e976-4d33-824a-5ea94444d15c', 'es', '¿Por qué una suposición equivocada a menudo funciona igual?', '["Corregirte también genera participación y ritmo", "Equivocarte baja la presión", "A las mujeres les gusta corregir a los hombres"]'::jsonb, 'Aciertes o no, ella tiene que participar para responder. Ese es el objetivo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94a93921-8975-4a5a-ac8a-918d2cfeb071', 'es', '¿Por qué deberías acercarte con curiosidad?', '["Oculta la atracción", "Evita el rechazo", "Funciona como un truco psicológico", "Baja la presión y la hace sentirse interesante"]'::jsonb, 'La gente se abre cuando se siente vista, no evaluada ni perseguida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95d93e33-2d1c-431f-a2f0-0ed76d7c559c', 'es', 'Gimnasio. Abres la conversación. Ella responde con calidez y luego se vuelve a poner los audífonos.', '["Abierta: respondió completo, lo que muestra interés", "Cortés: respondió por educación, pero no le interesa seguir", "Fría: un gesto grosero que indica que te vayas de inmediato"]'::jsonb, 'Te reconoció y luego marcó un límite; retírate sin alargarlo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('96cd2c07-1109-4ded-b869-cec66cf863b9', 'es', 'Abres de forma directa en un bar. Llega su amiga y ella gira un poco el cuerpo hacia ella.', '["Seguir hablando sin ajustar nada", "Competir por su atención", "Señalarle que se giró", "Saludar a la amiga o despedirte limpiamente"]'::jsonb, 'Saber leer la situación significa adaptarte cuando la dinámica cambia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97f948e5-43c9-49fb-91ea-249d0532afa8', 'es', 'En una fiesta, ella está junto a las bebidas. ¿Qué apertura directa encaja mejor?', '["“Te vi desde el otro lado y tenía que venir a conocerte.”", "“La música está fuerte, ¿no?”", "“¿Sabes dónde está el baño?”", "“¿Vienes mucho por aquí?”"]'::jsonb, 'Expresar tu interés con claridad encaja con naturalidad en un evento social.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('99e493d5-07b4-4d19-ad59-483e3579a8d1', 'es', '¿Qué hace eficaz el planteamiento de una apertura de opinión?', '["Explica por qué se lo preguntas justo a ella y no a cualquiera", "Presenta su punto de vista como valioso e importante", "Crea un debate que genera tensión y atracción"]'::jsonb, 'La gente se ilumina cuando su punto de vista importa. Sentirse valorada genera participación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a58e14a-b997-4eae-a453-494d620dffc6', 'es', 'Bar. Le dices: “Se nota que eres la responsable del grupo, la que lleva a todos a casa”. ¿Qué funciona?', '["La suposición concreta la obligó a responder y participar de inmediato", "Siente curiosidad por saber cómo llegaste a esa conclusión sobre ella", "Las dos anteriores"]'::jsonb, 'Las suposiciones concretas obligan a responder y generan participación inmediata.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c7e0b10-8bac-4319-8672-b7ce62646374', 'es', 'Estás junto a ella en un bar lleno de gente. ¿Qué aperturas indirectas podrías usar?', '["Preguntarle si el bar siempre está así de lleno", "Preguntarle qué va a pedir", "Decirle que es atractiva", "Pedirle su Instagram"]'::jsonb, 'Comentar algo del entorno se siente como sumarse, no como interrumpir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9cf11184-5b92-4e5e-ac1b-12519aa0d194', 'es', 'Sonríe por cortesía, pero vuelve a su celular después de una respuesta breve. ¿Qué indica esto?', '["Que te tolera por educación, no un interés genuino", "Mucha receptividad escondida por timidez", "Un rechazo frío que exige insistir", "Una invitación abierta a seguir"]'::jsonb, 'Una sonrisa cortés con desconexión muestra neutralidad, no implicación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fb3d329-54bd-4b72-a37a-6435bb2ff6a4', 'es', 'Comentas lo mucho que tardan en servir las bebidas. Ella sonríe y te da la razón con entusiasmo.', '["Está molesta y desahogándose, no necesariamente interesada", "Está probando si le das la razón en sus quejas", "Te devuelve la energía y sigue en la conversación"]'::jsonb, 'Una respuesta entusiasta que sigue el tema muestra interés.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a02bd67f-f7f7-4331-a001-13bf4277f3f7', 'es', '¿Por qué abrir con “Tengo una pregunta” funciona mejor que hacer la pregunta directamente?', '["Muestra respeto al pedir permiso antes de quitarle tiempo", "Crea expectativa y curiosidad antes de la pregunta en sí", "Le da tiempo para prepararse mentalmente para participar"]'::jsonb, 'Anunciar la pregunta despierta curiosidad primero. Una pregunta directa no crea expectativa.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a08ba78a-da12-481b-ae11-9fc1b34e1ee4', 'es', '¿Qué es lo esencial sobre cómo nacen las conexiones?', '["Alguien tiene que estar dispuesto a hablar primero", "Surgen por arte de magia, sin esfuerzo", "Esperar siempre da mejores resultados", "El silencio invita a relaciones más profundas"]'::jsonb, 'Cada amigo que tienes existe porque uno de los dos abrió la boca primero.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a0996b03-70aa-45f2-8b9b-1e136e46396e', 'es', 'Abres con un comentario sobre la situación. Ella se ríe y añade un detalle propio. ¿Qué haces?', '["Pasar a un cumplido directo", "Seguir con el tema y profundizar un poco", "Pedirle el número de inmediato", "Tomarle el pelo de forma juguetona"]'::jsonb, 'Que aporte algo indica participación. Profundizar mantiene el ritmo natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2802fe7-bfee-46b8-9b7a-3b8797515730', 'es', 'Cafetería. Ella te devuelve la energía. El barista dice su nombre. Ella dice: “¡Ay, soy yo, perdón!”. ¿Qué es esto?', '["Abierta, pero interrumpida: proponle rápido sentarse juntos", "Cortés: usó la bebida como excusa cómoda para irse", "Interrupción externa: no es una señal; mira si vuelve después de recoger su bebida"]'::jsonb, 'Había participación antes de la interrupción; mira si vuelve después.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a281e41d-8c59-42aa-8e23-5071d84c9c8c', 'es', '¿Por qué funciona plantear “Mi amigo y yo estamos discutiendo…”?', '["Despierta curiosidad por saber de qué va la discusión", "Pone su opinión como la que decide, y eso la hace sentirse valorada", "Demuestra prueba social porque tienes amigos"]'::jsonb, 'Plantear un debate o un dilema invita a dar su opinión, y eso la hace sentirse valorada e incluida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a445b565-f83a-4031-9b70-7201a9b11bc3', 'es', '¿Qué transmites cuando llevas el rumbo de la conversación?', '["Seguridad", "Liderazgo", "Dirección", "Todas las anteriores"]'::jsonb, 'Elegir el tema muestra seguridad y liderazgo; marca el rumbo en lugar de esperar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a51060bf-7646-4967-a8bf-730e53f6714d', 'es', '¿Por qué abrir con “Hola, tengo una pregunta para ti” despierta tanta curiosidad?', '["Genera incertidumbre: quiere saber cuál es la pregunta", "Demuestra seguridad al interrumpir lo que estaba haciendo", "Te presenta como alguien que necesita algo, y eso le baja la guardia"]'::jsonb, 'Cuando la información está incompleta, el cerebro busca cerrarla; úsalo para atraer su atención.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a95654fc-2f4a-4b06-a6d7-ce66be1aaac1', 'es', 'Los dos están mirando libros en una librería. ¿Qué aperturas indirectas podrías usar?', '["Preguntarle si conoce este libro", "Decirle que te llamó la atención", "Pedirle su número", "Comentar lo bueno que es ese autor"]'::jsonb, 'Las aperturas basadas en lo que observas se integran en el momento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ab9eedd4-bf67-486a-8b3c-938ef10f4137', 'es', '¿Por qué tiene sentido acercarte en lugar de quedarte quieto?', '["No actuar garantiza el fracaso; actuar crea posibilidades", "Acercarte genera atracción más rápido", "Actuar garantiza seguridad"]'::jsonb, 'Si no haces nada, no puede pasar nada. Si actúas, algo puede pasar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ad29d82a-7cad-4f44-8cd0-826bc8d6d751', 'es', 'Un chico se queda callado en una fiesta mientras los demás conectan. ¿Qué le falta?', '["Un mejor momento", "Estatus social", "Amigos con quienes hablar", "Disposición para participar"]'::jsonb, 'Iniciar una conversación es el gesto sencillo que crea conexiones.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ada0ea94-3879-4702-b335-f62a57dd6045', 'es', '¿Por qué es tan fácil confundir una respuesta cortés con interés?', '["Incluye contacto visual y amabilidad", "Las mujeres evitan rechazar de forma tajante", "Los hombres proyectan su deseo en señales neutras", "Todas las anteriores"]'::jsonb, 'Las señales corteses son suaves a propósito; fíjate más bien en si su atención y sus preguntas se mantienen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ae78311f-d702-432d-971c-a612871a0e09', 'es', 'Te sonríe levemente y luego se da la vuelta. ¿Qué sugiere la regla de los tres segundos?', '["Analizar su sonrisa para medir su interés", "Esperar una señal más clara antes de moverte", "Acercarte de inmediato, antes de empezar a darle vueltas", "Planear bien tus palabras primero"]'::jsonb, 'Actuar rápido se adelanta a la lista creciente de excusas que tu cerebro inventa para no ir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b147a697-dedb-4919-b533-e070ef0767f6', 'es', '¿Qué evita que se activen sus respuestas automáticas de amenaza?', '["Acercarte desde un ángulo en que te vea", "No bloquearle la salida ni el movimiento", "Detenerte a una distancia respetuosa", "Todas las anteriores"]'::jsonb, 'Respetar su espacio personal ayuda a que la interacción se sienta tranquila y natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b22764cf-ce02-4bf8-8eb7-5fb7926333ed', 'es', 'Ves que su libro tiene una portada interesante. ¿Qué podrías decir primero para despertar curiosidad?', '["“¿Qué libro es ese?”", "“¿Lees mucho?”", "“Se ve interesante.”", "“Te tengo que preguntar algo sobre ese libro que tienes.”"]'::jsonb, 'El planteamiento crea curiosidad antes de revelar la pregunta.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b2eb7c50-c714-4003-a310-0084c29f7fcc', 'es', '¿Por qué las aperturas indirectas quitan presión?', '["Son frases ensayadas que funcionan en muchas situaciones", "No la obligan a decidir de inmediato si le atraes", "Disfrazan tu intención detrás de una conversación casual y creíble"]'::jsonb, 'Las aperturas indirectas se sienten como una continuación del momento que los dos ya están viviendo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b32bbd22-abe6-4fd4-9f13-deaaad94298d', 'es', 'Ves que su funda de celular tiene un diseño de plantas. ¿Qué apertura muestra curiosidad?', '["“Qué bonita funda.”", "“¿Te gusta la jardinería?”", "“Tu celular se ve bien.”", "“¿Te gustan las plantas? Esa funda tiene unas muy bonitas.”"]'::jsonb, 'La curiosidad por sus experiencias invita a una conexión real, sin intenciones ocultas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b58b39df-93ba-4f7a-bed5-8eaaa5aa7a37', 'es', 'Ella está bailando con sus amigas. Cruzan miradas y te sonríe. ¿Qué haces?', '["Esperar a que deje de bailar para acercarte", "Ponerte a bailar cerca de ella", "Volver a cruzar miradas antes de moverte", "Acercarte a ella y al grupo"]'::jsonb, 'De noche el ambiente cambia rápido, así que cada demora convierte las señales en oportunidades perdidas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5ec6ba9-5bbb-4681-a239-50a711d681dd', 'es', '¿Por qué funcionan tan bien las aperturas de debate o discusión?', '["Crean un conflicto juguetón que genera tensión sexual", "La involucran para resolver una cuestión con su opinión, y eso la hace sentirse importante", "Demuestran prueba social (estabas hablando con un amigo)"]'::jsonb, 'Plantear un debate o un dilema invita a dar su opinión, y eso la hace sentirse valorada e incluida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b723c51c-c180-4bd0-900c-be66fdc3c190', 'es', '¿Cuál es la mayor diferencia entre cortesía y receptividad?', '["El tono de voz", "Cuánto sonríe", "Cuánto se implican los dos", "La cercanía física"]'::jsonb, 'La receptividad incluye participación y curiosidad; la cortesía solo busca que todo fluya sin roces.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b765cb2c-14d9-49bf-b793-eeb611ababea', 'es', '¿Qué pasa cuando solo te acercas en condiciones perfectas?', '["Cada acercamiento parece tener más en juego porque es poco frecuente", "Haces pocos intentos en comparación con participar constantemente", "La calidad de tus acercamientos mejora al ser selectivo"]'::jsonb, 'Esperar las condiciones perfectas reduce tus intentos y aumenta la presión en cada uno.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b76c6af0-9df1-46cb-92cc-9c07b2d1404f', 'es', '¿Por qué los límites de tiempo son eficaces para quitar presión?', '["Sabe que no va a quedar atrapada en una conversación sin fin con un desconocido", "Demuestra que respetas su tiempo y no lo vas a desperdiciar", "Menos tiempo significa menos riesgo de un rechazo incómodo"]'::jsonb, 'Decir que no te vas a quedar mucho rato quita presión; úsalo al principio.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b86940dc-da66-4fd6-a19f-bbbca988a036', 'es', '¿Qué ajustes físicos reducen la ansiedad que transmites?', '["Caminar a un ritmo constante, sin prisa ni dudas", "Mantener los hombros atrás y abajo, no levantados ni encogidos", "Mirar fijamente a la que te interesa para mostrar enfoque e intención"]'::jsonb, 'Un ritmo constante y los hombros relajados reducen la tensión visible antes de que hables.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ba3e426f-7282-4d49-a10f-46c3512816fc', 'es', 'Responde de forma neutra, das un paso claro y te dice que no. ¿Qué deberías hacer?', '["Darle las gracias y despedirte con calma", "Plantearlo de otra forma y volver a intentarlo", "Justificar tu interés", "Cambiar de tema"]'::jsonb, 'Un no marca un límite claro; acéptalo con calma y despídete con aplomo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb7584e8-d1df-4dc9-a2bf-59a289ba6852', 'es', '¿Qué pasa cuando te limitas a responder en lugar de marcar el rumbo?', '["La interacción necesitaba más tiempo antes de avanzar", "Le cedes el tono: ella no va a avanzar por ti", "El momento mejora antes de avanzar"]'::jsonb, 'Cuando dejas de llevar la conversación, el ritmo se apaga; toma la iniciativa para que la interacción avance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc490fe2-1fae-42f6-b95e-718da8dccc05', 'es', '¿Por qué leer pronto las señales es esencial para una interacción respetuosa?', '["Su comportamiento inicial muestra cuánto margen tienes para seguir", "Las mujeres necesitan sentirse seguras antes de mostrar interés", "Las primeras señales evitan que cruces límites que ella no ha abierto", "Todas las anteriores"]'::jsonb, 'Su comodidad va primero; usa las señales para decidir cuándo seguir y cuándo aflojar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc5cb121-8a63-45f6-8e11-7d46e1ff9ec2', 'es', '¿Qué rasgos fortalecen la actitud de un hombre?', '["Creer claramente en sí mismo", "Estar cómodo con el rechazo", "Llevar el rumbo", "Buscar validación"]'::jsonb, 'Creer en ti y liderar refuerzan tu actitud; evita los comportamientos que buscan aprobación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c1dd9ccd-317b-4320-a1f4-5bbb6553f846', 'es', 'Te acercas. Ella sonríe, se gira hacia ti y te pregunta “¿Qué tal?” en un tono cálido.', '["Abierta: está receptiva; sigue construyendo la interacción", "Cortés: está siendo amable; prueba primero con una frase más", "No está claro: necesitas más información para saber cuánto le interesas"]'::jsonb, 'Cuando se implica con preguntas y una postura abierta, el interés está ahí; mantén el ritmo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c229e235-368e-47aa-9571-c1345d6402cf', 'es', 'Te acercas a una mujer en una cafetería. ¿Qué apertura puede hacer que se sienta valorada?', '["“Hola, ¿vienes mucho por aquí?”", "“Necesito la opinión de una mujer sobre algo.”", "“¿Qué estás tomando?”", "“Te ves muy bien hoy.”"]'::jsonb, 'Pedir su criterio de forma explícita realza su papel y despierta su participación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c321230f-a277-4593-bdeb-01167899a30c', 'es', 'Supermercado. Le dices: “Pareces muy fan de la comida sana. ¿Me equivoco?”. Ella se ríe. ¿Qué está funcionando?', '["La suposición juguetona la involucró y creó un ida y vuelta con humor de inmediato", "Demostraste seguridad con una afirmación atrevida", "Despertaste curiosidad por saber por qué pensaste que cuida su salud"]'::jsonb, 'Risa más corrección significa participación; quédate en ese tono juguetón y amplíalo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c36a094c-8b8b-4c97-b801-f551071a78ed', 'es', 'Lleva ropa artística de estilo vintage. ¿Qué apertura usa bien una suposición?', '["“Me encanta tu estilo. ¿Dónde sueles comprar?”", "“Tienes pinta de trabajar en algo creativo. ¿Me equivoco?”", "“Seguro que compras en tiendas de segunda mano, ¿verdad?”", "Cualquiera de las dos suposiciones: la del trabajo creativo o la de la segunda mano"]'::jsonb, 'Las dos la obligan a participar para confirmar, negar o explicar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c387493a-0ebd-41c3-b083-1a639c5a593d', 'es', '¿Por qué disculparte al principio debilita una apertura?', '["Baja tu estatus", "Indica que estás interrumpiendo", "Le cede el control a ella", "Todas las anteriores"]'::jsonb, 'Disculparte te presenta como una interrupción; abre como si estuvieras en tu lugar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3fe310a-e657-4693-8a1b-acee8218f2a8', 'es', '¿Qué pauta hace que una apertura con una suposición parezca perspicaz y no al azar?', '["Decirla con seguridad", "Basarla en algo que se pueda observar", "Mantenerla vaga", "Hacerla desafiante"]'::jsonb, 'Basar las suposiciones en señales visibles hace que parezcan pensadas y no arbitrarias.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c41c83a5-d2fe-4cdf-b37f-bcec922ef1d8', 'es', '“Mi amigo cree que estoy loco, pero yo creo que la gente que…”. ¿Qué logra esta apertura?', '["Plantea un debate en el que su opinión decide", "Muestra tu personalidad y tu sentido del humor para generar atracción", "La pone a la defensiva porque le estás coqueteando"]'::jsonb, 'Plantear un debate o un dilema invita a dar su opinión, y eso la hace sentirse valorada e incluida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c4e94987-68b3-4c33-b481-27950bb88e63', 'es', '¿Qué ambientes son mejores para las aperturas con intención directa?', '["Supermercados", "Bibliotecas tranquilas", "Salas de espera del médico", "Bares y discotecas"]'::jsonb, 'La intención directa encaja en ambientes pensados para conocer gente, como bares y discotecas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c4ec10a6-7307-4d33-b4ac-bab091417d95', 'es', '¿Por qué disculparte en tu apertura te impide marcar el tono?', '["Da por hecho que lo que ella hace es más importante", "Pide permiso en lugar de llevar la conversación", "Presenta tu presencia como una interrupción", "Muestra que te adueñas del momento con seguridad"]'::jsonb, 'Disculparte te presenta como una interrupción, no como una opción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c728f4f6-0836-4faf-b386-b10c475ae132', 'es', '¿Por qué las aperturas indirectas quitan más presión que las directas?', '["Declaran de inmediato un interés romántico", "Hacen que el acercamiento parezca un momento casual compartido", "Permiten que la interacción se desarrolle con naturalidad", "Esconden la intención detrás de un comentario sobre la situación"]'::jsonb, 'Un contexto compartido hace que tu entrada se sienta esperable y sea fácil responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c9f1e798-7318-4c31-b9db-3d51fbde0554', 'es', '¿Cuál es la razón principal por la que las aperturas con una suposición generan participación?', '["Transmiten más seguridad que las preguntas", "Indican pronto una intención romántica", "La obligan a responder de verdad en lugar de contestar en piloto automático"]'::jsonb, 'Las suposiciones piden una respuesta. Al instante, ella participa corrigiendo o confirmando.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cad92129-8727-4718-bff9-4ab66c366d32', 'es', '¿Por qué las aperturas de opinión generan tanta participación al principio?', '["Hacen que sienta que su perspectiva es importante", "La presentan como alguien cuyo criterio importa", "Son interesadas y fáciles de descartar", "Ayudan porque valoran lo que ella aporta"]'::jsonb, 'La gente responde cuando se siente escuchada y tomada en serio.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cb1b3910-7f46-4638-b7ba-949483f7d10a', 'es', 'Bar. Se fueron con ella a una zona más tranquila. ¿Qué sigue?', '["Seguir conversando y proponer verse otro día", "Pedirle su contacto ahora, mientras el ritmo es bueno", "Proponer ir juntos a otro lugar", "Pedirle su número o proponer ir juntos a otro sitio, según la logística y sus señales"]'::jsonb, 'Con un buen ritmo toca dar el siguiente paso: asegurar el contacto o proponer seguir en otro lado si sus señales dicen que sí.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ccb554b7-2aa7-47d7-a64b-d4d9612a37a1', 'es', '¿Por qué ciertos ángulos y distancias al acercarte generan incomodidad?', '["Activan respuestas automáticas de amenaza", "Le bloquean el movimiento o una posible salida", "Hacen que tu intención no se vea mientras te acercas", "Siempre muestran mucha seguridad"]'::jsonb, 'Un mal ángulo o una mala distancia se sienten invasivos, antes de cualquier decisión consciente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cd75e2e6-d17a-4bb7-93e9-0f592f46fef8', 'es', '¿Por qué tu planteamiento tiene que ser más interesante que lo que ella estaba haciendo?', '["Si no, volverá a lo suyo", "Los humanos estamos programados para prestar atención a lo interesante", "Tienes que captar su atención para competir con las distracciones", "Todas las anteriores"]'::jsonb, 'Todo es cierto: si tu planteamiento no es más atractivo que lo que ya estaba haciendo, vuelve a ello.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ceadc18e-3007-4ed0-beba-55eb062fbd75', 'es', 'La conversación va bien. Te pregunta de dónde eres. Respondes, ¿y luego?', '["Le haces otra pregunta para seguir llevando la conversación", "Te extiendes en tu respuesta para seguir hablando", "Dejas que ella haga la siguiente pregunta para mostrar que escuchas"]'::jsonb, 'Marcar el tono significa llevar la conversación hacia delante; responde y luego reconduce.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cf063d07-0835-4825-9d56-79f6e3255038', 'es', 'Le dices que te pareció atractiva. Te da las gracias, pero sigue respondiendo con frases cortas.', '["Insistir para mostrar seguridad", "Pasar a una charla casual para aliviar la tensión", "Despedirte con educación y dejarla cómoda"]'::jsonb, 'Respuestas mínimas después de mostrar una intención clara significan que el interés no es mutuo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0ec47ae-1140-4d62-b956-39af81780946', 'es', '¿Qué comportamientos indican que sabes marcar el tono?', '["Una certeza tranquila", "La indecisión", "Llevar las transiciones", "Necesitar que te den la razón"]'::jsonb, 'El tono se marca dando dirección, no buscando acuerdo; guía en lugar de comprobar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d1f7d186-8772-4b75-bb24-e34679605860', 'es', 'Los dos están paseando a sus perros y los perros empiezan a jugar. ¿Qué funciona como apertura indirecta?', '["Comentar lo bien que se llevan los perros", "Elogiarla a ella o lo bonito que es su perro", "Preguntarle de qué raza es su perro", "Preguntarle si viene a menudo a este parque"]'::jsonb, 'Quedarte en la experiencia compartida deja que la comodidad crezca de forma natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d3daff27-e652-43a8-8f20-af94b5be0f32', 'es', 'En la calle. Ella es amable, pero no sabes si le interesas. ¿Cuál es la mejor jugada?', '["Caminar a su lado y seguir hablando", "Bajar tu energía e ir a su ritmo", "Decirle: “Me caes bien. ¿Tomamos un café algún día?”"]'::jsonb, 'Una invitación sencilla le da una forma clara de aceptar o declinar, sin forzar que la conversación siga.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d43846a5-78ac-402f-95a0-7cfcb54078ce', 'es', '¿Por qué ayuda aclarar las cosas en lugar de quedarte dando vueltas después de respuestas neutras?', '["Le da una elección clara entre sí y no", "Acorta un momento incómodo", "La obliga a revelar si le atraes", "Elimina la necesidad de adivinar"]'::jsonb, 'Una frase clara elimina la ambigüedad: revela si su amabilidad es interés o simple cortesía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d466b22a-5014-4620-9cfa-19217d091ad6', 'es', '¿Cuáles son aperturas indirectas eficaces?', '["Comentar algo del entorno", "Preguntar por la situación en la que están los dos", "Fijarte en experiencias compartidas", "Elogiar su aspecto"]'::jsonb, 'Un contexto compartido hace que tu entrada se sienta esperable y sea fácil responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d61d2413-5ee2-43c8-8cce-8d6030c1879e', 'es', '¿Qué te quita el control del tono en una apertura?', '["Hacer una afirmación directa en lugar de pedir permiso", "Disculparte por acercarte o por interrumpir", "Preguntarle primero si puedes hablar con ella"]'::jsonb, 'Disculparte te presenta como una interrupción; abre como si estuvieras en tu lugar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d743d469-5774-4931-80b8-cf68fa8054d1', 'es', 'Dudas 30 segundos y otro se le acerca primero. ¿Qué lo causó?', '["Darle tiempo a tu cerebro para convencerte de no hacerlo", "No tener una buena frase de apertura", "Su claro desinterés", "No sentirte lo bastante listo"]'::jsonb, 'Actuar rápido impide que la duda crezca. Muévete en los tres segundos después de verla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d76f2c05-59de-4480-a3a4-8dbe27fb2854', 'es', '¿Por qué funciona la regla de los tres segundos?', '["Te da tiempo de preparar una apertura perfecta", "Te permite evaluar primero cuánto le interesas", "Actúas antes de que la detección de amenazas genere resistencia"]'::jsonb, 'La regla funciona porque actúas antes de que tu cerebro invente motivos para no hacerlo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('daf41a36-31b3-4cc7-b731-be0601f73a66', 'es', '¿Por qué las aperturas de curiosidad captan mejor la atención?', '["Bajan las defensas", "Crean una obligación", "Retrasan el juicio", "Despiertan interés"]'::jsonb, 'La curiosidad funciona porque atrae la atención de forma natural; abre con algo que intrigue.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc0ff18e-1928-43e2-b403-e3cb7a6b3ab2', 'es', 'La conversación se va hacia un tema aburrido. Marcar el tono significa:', '["seguirla para mostrar que escuchas y te interesa", "llevarla a un tema que te parezca más interesante, sin despreciar el suyo", "decirle que prefieres hablar de otra cosa"]'::jsonb, 'Reconduce reconociendo el momento y llevando la charla hacia temas con más energía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc4c48ee-7f80-40c8-8355-cfd7dfdf8159', 'es', 'Cafetería. Abres la conversación. Ella sonríe con calidez, pero responde con frases cortas y se gira hacia otro lado.', '["Abierta: la sonrisa cálida indica interés a pesar de las respuestas breves", "Cortés: sonríe por amabilidad, pero su lenguaje corporal muestra reserva", "No está claro: las señales mixtas exigen más interacción para evaluar"]'::jsonb, 'Cuando las respuestas son breves y se gira hacia otro lado, respeta el límite y despídete.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ddf26019-643c-48e3-99bd-8ed12168ae51', 'es', 'En el metro ves a una mujer leyendo un libro que te encanta. ¿Qué garantiza el fracaso?', '["Acercarte y que te rechace", "Dudar y no acercarte", "Esperar a que ella hable primero", "Sonreír sin decir nada"]'::jsonb, 'No actuar garantiza cero posibilidades; actuar crea resultados posibles.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df7b348f-77a6-43b4-b9c2-72ba495cd148', 'es', 'Sonríe, responde y te hace una pregunta a ti también. ¿Cuál es la mejor jugada?', '["Avanzar rápido", "Frenar la interacción", "Hacerle un cumplido", "Seguir con naturalidad"]'::jsonb, 'Cuando te devuelve el interés, sigue con naturalidad para crear ritmo sin forzarlo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0a819cd-0a51-464f-ae01-bb50bf45ca1b', 'es', 'La saludas. Te dice su nombre, sostiene la mirada y te pregunta de dónde eres.', '["Está abierta y se está implicando en la interacción", "Es cortés y sigue las normas sociales", "Está reuniendo información para decidir más tarde"]'::jsonb, 'Devolverte su nombre y hacerte preguntas indica un interés activo, no una cortesía pasiva.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0b6a830-3f63-4d2b-b958-5db45a154beb', 'es', '¿Por qué es un error tan común confundir cortesía con receptividad?', '["Los hombres quieren ver interés, así que interpretan de más la cortesía", "A las mujeres se les enseña a ser educadas, y los hombres lo confunden con atracción", "Las señales corteses incluyen sonrisas y calidez, que los hombres leen como interés", "Todas las anteriores"]'::jsonb, 'Las señales corteses son suaves a propósito; fíjate más bien en si su atención y sus preguntas se mantienen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e1d6b84b-cc78-420d-8d46-30d10f8f2b0a', 'es', 'Participa con calidez, te toca el brazo, te hace preguntas, pero luego dice: “Ya llegó mi Uber”.', '["Abierta con poco tiempo: intercambien contactos antes de que llegue el Uber", "Cortés: el contacto y las preguntas eran amabilidad antes de una salida planeada", "Mixta: mencionó un límite de tiempo"]'::jsonb, 'Mucha participación más un límite de tiempo real es tu señal para intercambiar números de inmediato.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2a6f6e8-963f-4da4-bfc3-a9cc1b615ab4', 'es', '¿Qué comportamientos indican un interés receptivo?', '["Da respuestas cortas, pero sostiene la mirada", "Gira todo el cuerpo hacia ti al responder", "Te hace preguntas o aporta a la conversación"]'::jsonb, 'Cuando se implica con preguntas y una postura abierta, el interés está ahí; mantén el ritmo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2e4a209-5fc0-4faf-a13c-67ed31a8a170', 'es', 'Solo te acercas cuando estás listo, en salidas planeadas. ¿Qué limita esto?', '["Tu cantidad total de práctica y de intentos", "Tus posibilidades de interacciones perfectas", "Tus estándares de apariencia"]'::jsonb, 'Esforzarte solo a veces mantiene pocos intentos y frena el desarrollo de tu habilidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e3b36edc-fa81-4ae9-ba6b-80b396e930c4', 'es', '¿Qué hace que una suposición equivocada funcione igual?', '["Puede que te corrija, y eso ya es participar", "Su corrección suele llevarla a explicar cómo es en realidad", "Equivocarte muestra vulnerabilidad, y eso genera confianza"]'::jsonb, 'Las suposiciones equivocadas generan participación a través de la corrección y la explicación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e549d946-f5c9-48d5-8ed3-03653b7ab3b6', 'es', 'Los dos están mirando libros en una librería tranquila. ¿Qué apertura quita presión?', '["“Pareces alguien que lee mucho.”", "“Te ves bien con un libro en la mano.”", "“¿Me das tu contacto?”", "“¿Has leído algo bueno de aquí últimamente?”"]'::jsonb, 'Una experiencia compartida en ese momento inicia la conversación con naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e5eae06f-7a14-4c9f-ab68-d799aa9f603d', 'es', 'Responde con buena actitud, pero dice: “Tengo que volver con mis amigas en un segundo”. ¿Qué haces?', '["Una respuesta abierta significa seguir, aunque haya mencionado un límite de tiempo", "Causar una buena impresión en poco tiempo y luego dejarla ir", "Respetarlo: reconocerlo y despedirte limpiamente o intercambiar contactos rápido"]'::jsonb, 'Que esté receptiva no elimina el límite de tiempo; sé breve o pasa rápido al siguiente paso.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6f7a034-55b9-4303-a1f2-e70269b09f81', 'es', 'Ves a una mujer con tatuajes artísticos. ¿Qué apertura genera participación?', '["“Hola, ¿cómo va tu noche?”", "“Pareces alguien que trabaja en algo creativo.”", "“¿A qué te dedicas?”", "“Te ves bien.”"]'::jsonb, 'Las suposiciones concretas la obligan a participar y responder de forma personal.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ea6aac0e-0b64-4be8-aa43-1990315262e0', 'es', 'Le dices: “Eres preciosa, tenía que saludarte”. Se sonroja, te da las gracias, pero responde con frases cortas.', '["Volver a elogiarla para mostrar que sigues interesado", "Bromear con lo tímida que es para crear comodidad", "Despedirte con elegancia: poca reciprocidad tras una apertura directa indica que no le interesas"]'::jsonb, 'Sonrojarse puede ser cortesía. Respuestas cortas después de una apertura directa significan que no le interesas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ed852bcc-77f4-436a-9582-103cc2537be6', 'es', 'Le dices: “Te vi y quería saludarte”. Se ríe, te saluda y te pregunta a qué te dedicas.', '["Solo está siendo cortés en un ambiente social", "Te devuelve el interés y está abierta a seguir", "Está sorprendida y gana tiempo para evaluar"]'::jsonb, 'Reírse y devolverte la pregunta indican reciprocidad y ganas reales de seguir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f0dd9eca-d510-4237-8ce4-290954082900', 'es', '¿Qué elementos hacen tu planteamiento más interesante que lo que ella está haciendo?', '["Hacer suposiciones juguetonas que la involucren de inmediato", "Pedirle su opinión sobre algo que le interese", "Ser más ruidoso o más enérgico que el ambiente que la rodea"]'::jsonb, 'La participación viene de involucrarla, no del volumen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f17c4317-4ac6-4db1-838b-c39a93c3de0f', 'es', 'Bar. Ella es amable, pero no sabes si le interesas. ¿Cuál es la mejor jugada?', '["Preguntarle: “¿Vienes conmigo a pedir algo de tomar?”", "Avanzar físicamente de forma atrevida", "Hacerle preguntas más profundas para conectar", "Esperar en silencio a ver si vuelve a hablarte"]'::jsonb, 'Una invitación sencilla le da una forma clara de aceptar o declinar, sin forzar que la conversación siga.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f2b0e5af-f8e1-480b-aa9a-969dfa406d42', 'es', 'Se gira hacia ti, sonríe con calidez, responde con detalle y se arregla el pelo mientras habla.', '["Muy abierta: girarse, sonreír, responder con detalle y tocarse el pelo muestran interés", "Cortés: está siendo amable y lo del pelo es casualidad", "Nerviosa: está ansiosa por la interacción, no necesariamente interesada"]'::jsonb, 'Varias señales positivas juntas indican receptividad; sigue adelante.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f2ebba26-20ab-4f42-bd4e-eda08aa656ef', 'es', '¿Por qué abrir con una disculpa debilita la interacción?', '["Mal momento", "Poca atracción", "Te presentas como una interrupción", "No estaba soltera"]'::jsonb, 'Disculparte te presenta como una interrupción; abre como si estuvieras en tu lugar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fb2737de-57ac-46ae-bfd8-662497358e2a', 'es', '¿Por qué el misterio funciona al plantear la conversación?', '["No sabe qué vas a decir después, y eso despierta curiosidad y atención", "Evita que te encasille y te descarte rápido", "A las mujeres les atraen por naturaleza los hombres misteriosos"]'::jsonb, 'El misterio despierta curiosidad por lo que viene después y capta su atención.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fdbb58fb-2105-465e-9bb2-95117c0d4ee4', 'es', 'Se gira por completo y sonríe, pero dice: “Hoy no tengo ganas de hablar con nadie”.', '["Rechazo cortés: a pesar del lenguaje corporal positivo, sus palabras muestran desinterés", "Prueba: quiere ver si insistes a pesar de su objeción", "Mixta: el cuerpo dice que sí y las palabras que no; insiste con suavidad"]'::jsonb, 'Un lenguaje corporal amable no anula un límite dicho en voz alta; reconócelo y despídete.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fdbdc05b-610e-4954-bace-34af89e1f619', 'es', 'Después de una apertura directa, se ríe un momento pero enseguida mira alrededor.', '["Subir la energía para recuperar su atención", "Pedirle el número antes de que se pierda el ritmo", "Dejar que la interacción termine con naturalidad"]'::jsonb, 'La risa puede ser cortesía; una atención dividida significa que es momento de retirarte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ff750d3c-1bf6-4368-bb6c-04dc1b70a29b', 'es', '¿Por qué los límites de tiempo funcionan a nivel psicológico?', '["El cerebro se relaja cuando el momento no parece un compromiso largo", "Ella baja la guardia al saber que no va a quedar atrapada en una conversación sin fin", "Crean una escasez que te hace parecer más valioso"]'::jsonb, 'Los límites quitan el miedo a quedarse atrapada, y eso aumenta la comodidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
